export default function ScannerPage() {
  const galleryInputRef = useRef<HTMLInputElement | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [scanResult, setScanResult] = useState<string | null>(null);
  const previewUrl = useObjectUrl(selectedFile);

  function handleGalleryChange(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0] ?? null;
    setSelectedFile(file);
  }

  function openCamera() {
    setIsCameraOpen(true);
  }

  function openGallery() {
    galleryInputRef.current?.click();
  }

  function clearSelection() {
    setSelectedFile(null);
    if (galleryInputRef.current) galleryInputRef.current.value = "";
    setScanResult(null);
  }

  async function handleScan() {
    setIsScanning(true);

    // BACKEND INTEGRATION START
    // Replace this demo block with a real backend call.
    // Example:
    // 1. send `selectedFile` to your scanner endpoint
    // 2. await the response from the backend
    // 3. store the response in `scanResult`
    // BACKEND INTEGRATION END

    // EXAMPLE SCAN START
    await new Promise((resolve) => setTimeout(resolve, 900));

    if (!selectedFile) {
      setScanResult("Demo scan: no image selected yet. Add a photo first, then connect the backend here.");
    } else {
      setScanResult(
        `Demo scan result for ${selectedFile.name}: likely recyclable plastic/metal packaging. Replace this with your backend response.`
      );
    }
    // EXAMPLE SCAN END

    setIsScanning(false);
  }

  return (
    <div className="flex min-h-screen flex-col bg-white font-sans dark:bg-black">
      <ScannerHeader />

      <ScannerBody
        file={selectedFile}
        previewUrl={previewUrl}
        scanResult={scanResult}
        isScanning={isScanning}
        onOpenCamera={openCamera}
        onOpenGallery={openGallery}
        onClear={clearSelection}
        onScan={handleScan}
      />

      <ScannerFooter />

      <input
        ref={galleryInputRef}
        type="file"
        accept="image/*"
        className="hidden"
        onChange={handleGalleryChange}
      />

      {isCameraOpen && (
        <CameraCaptureModal
          onCapture={(file) => setSelectedFile(file)}
          onClose={() => setIsCameraOpen(false)}
        />
      )}
    </div>
  );
}

