export default function ScannerPage() {
  const galleryInputRef = useRef<HTMLInputElement | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [scanResult, setScanResult] = useState<WasteResult | null>(null);
  const [scanError, setScanError] = useState<string | null>(null);
  const previewUrl = useObjectUrl(selectedFile);
  const router = useRouter();
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userData, setUserData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Check if user is logged in
    const userExists = localStorage.getItem("user");

    if (userExists) {
      try {
        const user = JSON.parse(userExists);
        setUserData(user);
        setIsAuthenticated(true);
      } catch (e) {
        // Invalid user data, redirect to StartPage
        router.push("/StartPage");
      }
    } else {
      // No user logged in, redirect to StartPage
      router.push("/StartPage");
    }
    setIsLoading(false);
  }, [router]);

  function handleGalleryChange(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0] ?? null;
    setSelectedFile(file);
    setScanResult(null);
    setScanError(null);
  }

  function openCamera() {
    setIsCameraOpen(true);
  }

  function openGallery() {
    galleryInputRef.current?.click();
  }

  function clearSelection() {
    setSelectedFile(null);
    if (galleryInputRef.current) galleryInputRef.current.value = "";
    setScanResult(null);
    setScanError(null);
  }

  async function handleScan() {
    if (!selectedFile) {
      return;
    }

    setIsScanning(true);
    setScanError(null);
    setScanResult(null);

    try {
      const base64Image = await fileToBase64(selectedFile);
      const mimeType = selectedFile.type || "image/jpeg";

      const response = await fetch(`${API_BASE_URL}/analyze`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          image: base64Image,
          mime_type: mimeType,
        }),
      });

      if (!response.ok) {
        const errorBody = await response.json().catch(() => null);
        const detail = errorBody?.detail ?? `Eroare server (${response.status}).`;
        setScanError(detail);
        return;
      }

      const data: WasteResult = await response.json();
      setScanResult(data);
    } catch (error) {
      const message =
          error instanceof Error
              ? error.message
              : "A apărut o eroare necunoscută la analizarea imaginii.";
      setScanError(message);
    } finally {
      setIsScanning(false);
    }
  }

  return (
      <div className="flex min-h-screen flex-col bg-white font-sans dark:bg-black">
        <ScannerHeader />

        <ScannerBody
            file={selectedFile}
            previewUrl={previewUrl}
            scanResult={scanResult}
            isScanning={isScanning}
            scanError={scanError}
            onOpenCamera={openCamera}
            onOpenGallery={openGallery}
            onClear={clearSelection}
            onScan={handleScan}
        />

        <ScannerFooter />

        <input
            ref={galleryInputRef}
            type="file"
            accept="image/*"
            className="hidden"
            onChange={handleGalleryChange}
        />

        {isCameraOpen && (
            <CameraCaptureModal
                onCapture={(file) => {
                  setSelectedFile(file);
                  setScanResult(null);
                  setScanError(null);
                }}
                onClose={() => setIsCameraOpen(false)}
            />
        )}
      </div>
  );
}

"use client";

import { type ChangeEvent, useEffect, useRef, useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faCamera,
  faComments,
  faClock,
  faHome,
  faImage,
  faMap,
  faXmark,
  faTrashCan,
  faUser,
  faTriangleExclamation,
  faRecycle, faUserGear,
} from "@fortawesome/free-solid-svg-icons";
import Link from "next/link";
import {useRouter} from "next/navigation";

const API_BASE_URL = "http://localhost:8000";

// ---------------------------------------------------------------------------
// Tipuri care reflectă WasteResult din backend (main.py)
// ---------------------------------------------------------------------------

type RecyclingPoint = {
  name: string;
  address: string;
  latitude: number;
  longitude: number;
  distance_km?: number | null;
  maps_url: string;
  open_now?: boolean | null;
  rating?: number | null;
};

type WasteResult = {
  item_name: string;
  waste_category: string;
  description: string;
  disposal_instructions: string[];
  warnings: string[];
  is_recyclable: boolean;
  recycling_points: RecyclingPoint[];
  local_bins: Record<string, unknown>[];
};

const CATEGORY_LABELS: Record<string, string> = {
  sticla: "Sticlă",
  plastic: "Plastic",
  baterii: "Baterii",
  electronice: "Electronice",
  hartie_carton: "Hârtie / Carton",
  metal: "Metal",
  organic: "Organic",
  periculos: "Periculos",
  altele: "Altele",
};

function useObjectUrl(file: File | null) {
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  useEffect(() => {
    if (!file) {
      setPreviewUrl(null);
      return;
    }

    const objectUrl = URL.createObjectURL(file);
    setPreviewUrl(objectUrl);

    return () => URL.revokeObjectURL(objectUrl);
  }, [file]);

  return previewUrl;
}

// Citește un File și îl transformă în base64 (fără prefixul data:...;base64,)
function fileToBase64(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const result = reader.result as string;
      const base64 = result.split(",")[1] ?? "";
      resolve(base64);
    };
    reader.onerror = () => reject(new Error("Nu am putut citi fișierul imagine."));
    reader.readAsDataURL(file);
  });
}

